BEGIN;

CREATE OR REPLACE FUNCTION master_norm(v text) RETURNS text
LANGUAGE sql IMMUTABLE AS $$ SELECT NULLIF(regexp_replace(upper(trim(v)), '\s+', ' ', 'g'), '') $$;
CREATE OR REPLACE FUNCTION master_rut(v text) RETURNS text
LANGUAGE sql IMMUTABLE AS $$ SELECT NULLIF(regexp_replace(upper(coalesce(v,'')), '[^0-9K]', '', 'g'), '') $$;
CREATE OR REPLACE FUNCTION master_rut_valid(v text) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE r text:=master_rut(v); body text; dv text; s int:=0; m int:=2; i int; e text;
BEGIN
 IF r !~ '^[0-9]{7,8}[0-9K]$' THEN RETURN false; END IF; body:=left(r,-1); dv:=right(r,1);
 FOR i IN REVERSE length(body)..1 LOOP s:=s+(substr(body,i,1)::int*m); m:=CASE WHEN m=7 THEN 2 ELSE m+1 END; END LOOP;
 e:=CASE 11-(s%11) WHEN 11 THEN '0' WHEN 10 THEN 'K' ELSE (11-(s%11))::text END; RETURN dv=e;
END $$;

CREATE TABLE IF NOT EXISTS marcas_master (marca_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre_canonico text NOT NULL,nombre_normalizado text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS modelos_master (modelo_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,marca_id bigint NOT NULL REFERENCES marcas_master(marca_id),nombre_canonico text NOT NULL,nombre_normalizado text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(marca_id,nombre_normalizado));
CREATE TABLE IF NOT EXISTS versiones_master (version_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,marca_id bigint NOT NULL REFERENCES marcas_master(marca_id),modelo_id bigint REFERENCES modelos_master(modelo_id),codigo_canonico text NOT NULL,codigo_normalizado text NOT NULL UNIQUE,descripcion_canonica text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS producto_aliases (producto_alias_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nivel text NOT NULL CHECK(nivel IN ('marca','modelo','version')),marca_id bigint REFERENCES marcas_master(marca_id),modelo_id bigint REFERENCES modelos_master(modelo_id),version_id bigint REFERENCES versiones_master(version_id),fuente text NOT NULL,valor_raw text NOT NULL,valor_normalizado text NOT NULL,match_method text NOT NULL,confidence numeric(4,3),validated boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(nivel,fuente,valor_normalizado));
CREATE TABLE IF NOT EXISTS sucursales_master (sucursal_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_sucursal_vta text NOT NULL UNIQUE,nombre_canonico text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sucursal_aliases (sucursal_alias_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,sucursal_id bigint REFERENCES sucursales_master(sucursal_id),fuente text NOT NULL,valor_raw text NOT NULL,valor_normalizado text NOT NULL,match_method text NOT NULL,validated boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(fuente,valor_normalizado));
CREATE TABLE IF NOT EXISTS personas_master (persona_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,usuario_canonico text NOT NULL UNIQUE,nombre_canonico text,confidence numeric(4,3),evidence_count integer NOT NULL DEFAULT 0,validated boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS persona_aliases (persona_alias_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,persona_id bigint REFERENCES personas_master(persona_id),fuente text NOT NULL,valor_raw text NOT NULL,valor_normalizado text NOT NULL,tipo_alias text NOT NULL CHECK(tipo_alias IN ('login','nombre')),match_method text NOT NULL,confidence numeric(4,3),validated boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(fuente,tipo_alias,valor_normalizado));
CREATE TABLE IF NOT EXISTS dealer_groups (dealer_group_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre_canonico text NOT NULL,nombre_normalizado text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dealers_master (dealer_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,rut_normalizado text NOT NULL UNIQUE,rut_dv text,razon_social_canonica text NOT NULL,nombre_comercial text,dealer_group_id bigint REFERENCES dealer_groups(dealer_group_id),identity_status text NOT NULL DEFAULT 'body_only' CHECK(identity_status IN ('body_only','rut_validated')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(rut_normalizado ~ '^[0-9]{7,8}$'),CHECK(rut_dv IS NULL OR rut_dv ~ '^[0-9K]$'));
ALTER TABLE dealers_master ADD COLUMN IF NOT EXISTS dealer_group_id bigint REFERENCES dealer_groups(dealer_group_id);
CREATE TABLE IF NOT EXISTS dealer_aliases (dealer_alias_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,dealer_id bigint REFERENCES dealers_master(dealer_id),fuente text NOT NULL,valor_raw text NOT NULL,valor_normalizado text NOT NULL,tipo_alias text NOT NULL,match_method text NOT NULL,validated boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(fuente,tipo_alias,valor_normalizado));
CREATE TABLE IF NOT EXISTS dealer_supervisor (dealer_supervisor_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,dealer_id bigint NOT NULL REFERENCES dealers_master(dealer_id),persona_id bigint NOT NULL REFERENCES personas_master(persona_id),vigente boolean NOT NULL DEFAULT true,valid_from date,valid_to date,fuente text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS master_conflicts (conflict_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,dominio text NOT NULL,natural_key text NOT NULL,conflict_type text NOT NULL,evidence jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','validated','rejected')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(dominio,natural_key,conflict_type));
CREATE INDEX IF NOT EXISTS idx_producto_alias_version ON producto_aliases(version_id); CREATE INDEX IF NOT EXISTS idx_persona_alias_persona ON persona_aliases(persona_id); CREATE INDEX IF NOT EXISTS idx_dealer_alias_dealer ON dealer_aliases(dealer_id); CREATE INDEX IF NOT EXISTS idx_dealers_master_group ON dealers_master(dealer_group_id); CREATE UNIQUE INDEX IF NOT EXISTS uq_dealer_supervisor_vigente ON dealer_supervisor(dealer_id) WHERE vigente; CREATE INDEX IF NOT EXISTS idx_conflicts_pending ON master_conflicts(dominio,status);
COMMIT;
